"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["332"],{9685(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>m,frontMatter:()=>s,contentTitle:()=>i,toc:()=>d,assets:()=>c});var o=JSON.parse('{"id":"explain/openat_faq","title":"AirVantage Connector FAQ","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/explain/openat_faq.md","sourceDirName":"explain","slug":"/explain/openat_faq","permalink":"/personal-av-docs/docs/explain/openat_faq","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/explain/openat_faq.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"AirVantage Connector FAQ","sidebar_label":"AirVantage Connector FAQ","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/openat_faq","format":"md"}}'),a=n(4848),r=n(8453);let s={title:"AirVantage Connector FAQ",sidebar_label:"AirVantage Connector FAQ",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/openat_faq",format:"md"},i,c={},d=[];function u(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/av/openat_faq",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(t.p,{children:'AirVantage Connector FAQ\nInitializing Table Of Contents...\nThis document explains the use case error that users often encouter while using the api connector during their development process\nConnecting bearer\nUsers must guarantee the successful mounted bearer (GPRS or ETH) before using the api connector. So, as the GPRS bearer is mouting, the following message must display (with wip_debug) :\n[GPRS]: open: -> DISCONNECTED\n[GPRS]: start: -> CONNECTING\n[GPRS]: GPRS CTX (cid=1) found\n[GPRS]: GPRS EVENT SETUP OK (cid=1): GPRS activate\n[GPRS]: GPRS CTX (cid=1) found\n[GPRS]: GPRS EVENT: 27 (cid=1)\n+WIND: 15,4,\u201C\n14\n\u2044\n03\n/03,13:20:48+04\u201D\n[GPRS]: GPRS CTX (cid=1) found\n[GPRS]: GPRS EVENT ACTIVATE OK (cid=1)\n[GPRS]: GPRS: -> CONNECTED\nIf the bearer cannot mounted for some reasons, users should check :\nIn case of GPRS :\nApn, User, Password of sim card in the setting of options GPRS\nRegistration of sim card on network with\nat+creg?\nSignal quality with\nat+csq\nError code return\nOnce, the bearer mounted successfully, the user application should register a callback function in the sending context in order to get a status of sending. Those following numbers are the error code returned by the parameter\ncontent.status\nin the\nsdb_sendCallbackInfo_t\nstructure. We can divide these codes in two different parts:\nProblem of configuration of sending context\n400  : Cannot parse the message from the server, the device cannot bind the message in the m3da protocol. So the parsing is broken. This problem may be due to the mal-formed request\n500  : Reject the sending request of the device by the server, the socket is closed by the server, the error may be due to either :\nThe socket is closed after a timeout defined in the server side (by default 30s). This case is nominal if there is any communication happened during the timeout\nThe socket is immediately closed by the server. It maybe  caused by the incompatible declaration (security, protocol, password, device ID \u2026) between device and server. Check also in the server side :\nsecurity\nServer model without security :\n<parameter name="authentication" value="none"/>\n<parameter name="cipher" value="none"/>\n-> Security defined on embeedbed application must be SDB_SND_SECU_NONE\nServer model with security authentication :\n<parameter name="authentication" value="hmac-md5"/>\n<parameter name="cipher" value="none"/>\n-> Security defined on embeedbed application must be SDB_SND_SECU_AUTH\nServer model with security encryption :\n<parameter name="authentication" value="hmac-md5"/>\n<parameter name="cipher" value="aes-cbc-128"/>\n-> Security defined on embeedbed application must be SDB_SND_SECU_ENC\nProtocol\n<protocol comm-id="SERIAL" type="M3DA" >\n->Device id defined on embeedbed application, must be the serial number'}),"\n",(0,a.jsxs)(t.p,{children:['<protocol comm-id="IMEI" type="M3DA" >\n->Device id defined on embeedbed application, must be the imei number\nPassword\nUsing the REST request to define the password\nPUT ',(0,a.jsx)(t.a,{href:"https://na.airvantage.net/api/v1/systems/a8b066e39b92412198c125190e1ed829",children:"https://na.airvantage.net/api/v1/systems/a8b066e39b92412198c125190e1ed829"}),'  //uid system\nContent-Type: application/json\n{\n"applications": [   {\n"uid": "45f3122fc8cb4bd38990f93a94647b36"   //uid model\n}],\n"communication" :   {\n"m3da" :    {\n"password" : "abcdef"\n}\n}\n}\nProblem of wip socket\n-986 : Timeout. For some reasons, the bearer is mounted, but it cannot communicate with server, this one leads to an error timeout on socket (note : it is different from the timeout error closed by the server with status=500). This error may be due to the bad port (different from 44900 or port blocked by operator network), DNS, tcp connection, operator network.\n-987 : Connection broken. This can happen when users try to send a lot of data (several tenths or hundreds of kbytes) on the same socket which takes time for sending. Either the network is bad, or the timeout defined on the server side is about 30s, this can break the socket communication. For the last cause, users should increase the cycle of sending data timer in their application, for example more than 2 mins. Otherwise, users should re-try to send data from callback function.\n-993 : Bad server address, cannot resolve a name to an IP address\nBad using of api connector\nSometimes, the bad using of api connector can cause some usual errors.\nAs users send a table or several tables to the server, they can encounter several error messages\n[sdb_send_data2buffer] Error cannot serialise the data to the buffer [status = -8]\n:  this error may be due to a difference between the number of column declared in table(s) and the number of values that we feed into table(s)\n[sdb_send_data2buffer] Error sdb_serialize [status = -4]\n: this error may be due to a overflow memory, users must increase the size buffer of sending context or reset the table with the\nsdb_reset(&table)\nfunction in order to free the memories occuped by table.']})]})}function m(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>i});var o=n(6540);let a={},r=o.createContext(a);function s(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);